writeLog("End Service");


function writeLog(msg , variable){  // vairable is optional
	var instanceID = "";
	try {instanceID = "Instance ID : "+tw.system.currentProcessInstance.id  +"  ::  ";} catch (err) {}
	variable == undefined ? variable =" " : variable = " : "+ variable ;
	var message = instanceID + tw.system.model.processApp.name  +" :: " + tw.system.serviceFlow.type +" :: "+ tw.system.serviceFlow.name +" :: "  + msg+" : " + variable;
	log.info( message);
}

